const promptSkills=window.promptSkillsService||new PromptSkillsService();const connections=window.connectionsService||new ConnectionsService();const skillGraphs=window.skillGraphsService||new SkillGraphsService();const runsApi=window.runsService||new RunsService();const app=document.querySelector('#app'),nodeTabs=document.querySelector('#skills'),viewButtons=[...document.querySelectorAll('[data-view]')];
const params=new URLSearchParams(location.search),runKey=params.get('run')||'',skillKey=params.get('skill')||'',base=window.GSW_BASE||'';
let run=null,activeNodeKey='',view='workflow',busy='',notice='',noticeError=false,sessionDraft=null,connectionState=null,testResult=null,settingsDirty=false,addSkillOpen=false,addSkillOptions=[];
let currentPublicUiOrigin='';
const currentPrompts=new Map();
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
