async function api(url,options={}){const r=await fetch(url,{cache:'no-store',headers:{'content-type':'application/json'},...options}),text=await r.text();let data=null;try{data=text?JSON.parse(text):null}catch{data={detail:text}}if(!r.ok)throw new Error(data?.Error||data?.error||data?.detail||data?.title||data?.Code||data?.code||`Request failed: ${r.status}`);return data}
