const completedSteps=node=>(node.stepDefinitions||[]).filter(s=>{const r=resultFor(node,s);return !!(r?.finalMarkdown||r?.summary)}).length;
function artifactUrl(nodeKey,a){return a.url||`${base}/api/runs/${encodeURIComponent(run.runKey)}/artifacts/${encodeURIComponent(nodeKey)}/${encodeURIComponent(a.artifactKey)}`}
function pill(value){return `<span class="status-pill ${esc(value)}">${esc(status(value))}</span>`}
const markdownAllowedTags=new Set(['h1','h2','h3','h4','h5','h6','p','br','hr','ul','ol','li','blockquote','pre','code','em','strong','del','s','mark','sub','sup','a','img','table','thead','tbody','tfoot','tr','th','td','span','div','dl','dt','dd','input']);
const markdownSafeAttributes={a:['href','title'],img:['src','alt','title'],code:['class'],pre:['class'],ol:['start'],li:['value'],th:['align'],td:['align']};
function safeMarkdownUrl(value){try{const url=new URL(String(value||''),location.origin);return ['http:','https:','mailto:'].includes(url.protocol)?value:''}catch{return ''}}
function sanitizeMarkdownNode(node){if(node.nodeType===Node.TEXT_NODE)return document.createTextNode(node.textContent||'');if(node.nodeType!==Node.ELEMENT_NODE)return null;const tag=node.tagName.toLowerCase();if(!markdownAllowedTags.has(tag))return null;if(tag==='input'){if(String(node.getAttribute('type')).toLowerCase()!=='checkbox')return null;const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.disabled=true;if(node.hasAttribute('checked'))checkbox.checked=true;return checkbox}const element=document.createElement(tag);for(const name of markdownSafeAttributes[tag]||[]){const value=node.getAttribute(name);if(value===null)continue;if(name==='href'||name==='src'){const safe=safeMarkdownUrl(value);if(safe)element.setAttribute(name,safe)}else if((tag==='ol'&&name==='start')||(tag==='li'&&name==='value')){if(/^-?\d+$/.test(value))element.setAttribute(name,value)}else element.setAttribute(name,value)}if(tag==='a'&&element.hasAttribute('href')){element.target='_blank';element.rel='noopener noreferrer'}for(const child of node.childNodes){const safe=sanitizeMarkdownNode(child);if(safe)element.appendChild(safe)}return element}
function sanitizeMarkdownHtml(html){const source=document.createElement('template'),output=document.createElement('template');source.innerHTML=String(html||'');for(const node of source.content.childNodes){const safe=sanitizeMarkdownNode(node);if(safe)output.content.appendChild(safe)}return output.innerHTML}
function markdown(source){if(!window.marked?.parse)throw new Error('Buffaly marked formatter is unavailable.');const renderer=new marked.Renderer();renderer.html=token=>esc(typeof token==='string'?token:token?.text||'');return sanitizeMarkdownHtml(marked.parse(String(source||''),{renderer}))}
