function parsePrompt(prompt){const work=String(prompt?.workPrompt||''),matches=[...work.matchAll(/^##\s+(.+)$/gm)],sections=[];for(let i=0;i<matches.length;i++){const title=matches[i][1].trim(),start=matches[i].index+matches[i][0].length,end=i+1<matches.length?matches[i+1].index:work.length;sections.push({title,markdown:work.slice(start,end).trim()})}return {sections,validationPrompt:String(prompt?.validationPrompt||'')}}
function renderTabs(){if(!run){nodeTabs.innerHTML='';return}nodeTabs.innerHTML=nodes().map(n=>`<button class="tab ${n.nodeKey===activeNodeKey?'active':''}" data-node="${esc(n.nodeKey)}">${esc(n.displayName)}<small>${completedSteps(n)}/${n.stepDefinitions?.length||0} steps · ${esc(status(n.status))}</small></button>`).join('');nodeTabs.querySelectorAll('[data-node]').forEach(b=>b.onclick=async()=>{activeNodeKey=b.dataset.node;renderTabs();render();await loadPrompt(activeNodeKey);render()})}
function connectionAction(){const primed=run.initializationStatus==='primed';return `<button class="button" data-prime ${busy?'disabled':''}>${primed||run.activeOperation?'Re-prime':'Prime'}</button>`}
const readablePrototype=name=>(name||'').replace(/^To/,'').replace(/Skill$/,'').replace(/([a-z])([A-Z])/g,'$1 $2').trim();
function addSkillPanel(){if(!addSkillOpen)return '';const existing=new Set(nodes().map(node=>node.actionPrototype)),available=addSkillOptions.filter(skill=>!existing.has(skill.prototypeName));return `<div class="add-skill-panel"><div class="add-skill-head"><b>Add another skill</b><p>Search the same full Buffaly skill catalog used when creating a run. The selected ProtoScript action loads into the same Buffaly session, ${esc(run.sessionKey)}.</p></div><label class="setup-search"><span>Search skills</span><input data-add-skill-search placeholder="Search by skill name or action prototype"></label><div class="skill-results add-skill-results">${available.length?available.map(skill=>`<button type="button" class="skill-option" data-add-skill-pick="${esc(skill.prototypeName)}"><span class="skill-icon">${skill.isInstalled?'+':'-'}</span><span><strong>${esc(skill.title||readablePrototype(skill.prototypeName))}</strong><small>${esc(skill.prototypeName)}</small></span><span class="skill-arrow">&gt;</span></button>`).join(''):'<div class="setup-placeholder">No matching skills found.</div>'}</div><button class="button" data-add-skill-cancel>Cancel</button></div>`}
function normalizeOrigin(value){return String(value||'').trim().replace(/\/+$/,'')}
function isLoopbackOrigin(value){try{const url=new URL(normalizeOrigin(value));return url.hostname==='127.0.0.1'||url.hostname==='localhost'}catch{return false}}
async function loadConfiguredPublicUiOrigin(){if(currentPublicUiOrigin)return currentPublicUiOrigin;try{const conn=await connections.GetConnection();currentPublicUiOrigin=normalizeOrigin(conn.connection?.publicUiOrigin)}catch{}if(currentPublicUiOrigin)return currentPublicUiOrigin;try{const local=await fetch(`${base}/workbench-config.local.json`,{cache:'no-store'});if(local.ok){const cfg=await local.json();currentPublicUiOrigin=normalizeOrigin(cfg.publicUiOrigin)}}catch{}return currentPublicUiOrigin}
function buffalySessionUiOrigin(connection){const configured=normalizeOrigin(connection?.publicUiOrigin||currentPublicUiOrigin);if(configured)return configured;const raw=normalizeOrigin(connection?.baseUrl);if(raw&&!isLoopbackOrigin(raw))return raw;return ''}
function buffalySessionUrl(){const base=buffalySessionUiOrigin(run.buffalyConnection),key=String(run.sessionKey||'').trim();return base&&key?`${base}/buffaly-agent-next.html?sessionKey=${encodeURIComponent(key).replace(/%20/g,'+')}`:''}
function sessionField(){const key=run.sessionKey||'',href=buffalySessionUrl();return `<label><b>Buffaly session</b>${href?`<a class="session-link" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(key)}</a>`:`<input value="${esc(key)}" readonly>`}</label>`}
function runBar(){const total=nodes().reduce((n,x)=>n+(x.stepDefinitions?.length||0),0),done=nodes().reduce((n,x)=>n+completedSteps(x),0),pct=total?Math.round(done/total*100):0,b=run.batchExecution,op=run.activeOperation,primed=run.initializationStatus==='primed',root=run.nodes?.[run.rootSkill],canValidate=root?.status==='awaiting_validation'&&!op,settled=!op&&!['running','pause_requested'].includes(b?.status);return `<section class="workflow-bar"><div class="workflow-row"><label><b>Bound run</b><input value="${esc(run.runKey)}" readonly></label>${run.displayName?`<label><b>Name</b><input value="${esc(run.displayName)}" readonly></label>`:''}${sessionField()}<span data-connection-action>${connectionAction()}</span><button class="button primary" data-batch-start ${busy||!primed||op||b?.status==='running'?'disabled':''}>${b?.status==='running'?'Batch running':'Run remaining steps'}</button>${canValidate?`<button class="button primary" data-final-validate ${busy?'disabled':''}>Run final validation</button>`:''}<button class="button" data-reload-workflow ${busy||!settled?'disabled':''}>Reload skill workflow</button><button class="button" data-add-skill ${busy||!run.sessionKey||!settled?'disabled':''}>Add skill</button>${b&&['running','pause_requested'].includes(b.status)?`<button class="button" data-batch-pause ${busy||b.status==='pause_requested'?'disabled':''}>${b.status==='pause_requested'?'Pause requested':'Pause after current step'}</button>`:''}${b?.status==='paused'?`<button class="button" data-batch-resume ${busy?'disabled':''}>Resume</button>`:''}<a class="button" href="${base}/api/runs/${encodeURIComponent(run.runKey)}/export" target="_blank">Export</a></div>${addSkillPanel()}${notice?`<div class="${noticeError?'error-banner':'operation-banner'}"><b>${noticeError?'Operation failed':'Workbench activity'}</b><p>${esc(notice)}</p></div>`:''}<div class="workflow-chips"><span>Revision ${run.revision}</span><span>${esc(status(run.initializationStatus))}</span><span>${done} of ${total} steps accepted</span><span>${nodes().filter(n=>n.status==='complete').length} of ${nodes().length} skills complete</span><span>Final validation ${esc(status(run.finalValidation?.status||(root?.status==='awaiting_validation'?'required':'not ready')))}</span><span>Root ${esc(run.rootSkill)}</span>${run.buffalyConnection?`<span class="init-chip">Bound: ${esc(run.buffalyConnection.displayName)} | ${esc(run.buffalyConnection.baseUrl)} | rev ${run.buffalyConnection.settingsRevision}</span>`:""}</div><div class="sticky-progress"><b>${op?`Running ${esc(op.stepKey)}`:b?`Server batch: ${esc(status(b.status))}`:'Ready'}</b><span class="toolbar-spacer"> ${pct}%</span><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div></section>`}
function validationEvidence(){const v=run.finalValidation;if(!v)return '';const passed=v.status==='passed',checked=(v.checks||[]).filter(c=>c.status==='pass').length,total=(v.checks||[]).length,when=v.validatedAtUtc?new Date(v.validatedAtUtc).toLocaleString():'';return `<section class="validation-evidence ${passed?'passed':'failed'}"><div class="validation-evidence-mark">${passed?'✓':'!'}</div><div><small>INDEPENDENT FINAL VALIDATION</small><h3>${passed?'Passed':'Needs correction'}</h3><p>${esc(v.summary||v.feedbackForRetry||'Validation completed.')}</p><div class="validation-facts"><span>${checked} of ${total} checks passed</span>${when?`<span>Validated ${esc(when)}</span>`:''}<span>Separate package validation criteria executed</span></div></div><div class="validation-evidence-actions"><a class="button ${passed?'primary':''}" href="${base}/api/runs/${encodeURIComponent(run.runKey)}/validation-evidence" target="_blank">Open validation evidence</a></div></section>`}
function overallOutput(node){const o=node.overallResult;if(!o)return '';const primary=o.artifacts?.find(a=>a.artifactKey===o.primaryArtifactKey)||o.artifacts?.[0],html=o.artifacts?.find(a=>a.mediaType==='text/html'),preview=html?artifactUrl(node.nodeKey,html):'';return `<section class="workflow-output"><div class="workflow-output-head"><div><small>BOUND SKILL OUTPUT</small><h2>${esc(o.title||node.displayName)}</h2><p>${esc(status(o.status))} · ${o.artifacts?.length||0} reviewable artifacts</p></div><div class="workflow-output-actions">${primary?`<a class="button primary" href="${esc(artifactUrl(node.nodeKey,primary))}" target="_blank">Open primary output</a>`:''}</div></div>${validationEvidence()}${html?`<div class="presentation-preview"><div><b>Presentation preview</b><a class="button" href="${esc(preview)}" target="_blank">Open full screen</a></div><iframe data-light-preview src="${esc(preview)}" title="${esc(o.title||node.displayName)} presentation preview" sandbox="allow-same-origin"></iframe></div>`:''}<ul class="workflow-output-list">${(o.artifacts||[]).map(a=>`<li><a href="${esc(artifactUrl(node.nodeKey,a))}" target="_blank">${esc(a.fileName||a.artifactKey)}</a><span>${esc(a.mediaType)}</span></li>`).join('')}</ul></section>`}
function stepArtifacts(node,result){if(!result?.artifacts?.length)return '';return `<div class="artifact-grid">${result.artifacts.map(a=>{const u=artifactUrl(node.nodeKey,a),image=String(a.mediaType).startsWith('image/');return `<div class="artifact-card"><h3>${esc(a.fileName||a.artifactKey)}</h3><p>${esc(a.mediaType)} · ${esc(a.artifactKey)}</p>${image?`<a href="${esc(u)}" target="_blank"><img class="artifact-preview" src="${esc(u)}" alt="${esc(a.fileName)}"></a>`:''}<a class="button" href="${esc(u)}" target="_blank">Open artifact</a></div>`}).join('')}</div>`}
function correctionFor(stepKey){return ['failed','invalidated'].includes(run.finalValidation?.status)?(run.finalValidation?.correctionPlan||[]).filter(c=>(c.stepKeys||[]).includes(stepKey)).map(c=>c.guidance).join('\n\n'):''}
function extractHtmlPreviews(source){const previews=[];const markdown=String(source||'').replace(/```html-preview\s+template=(\S+)\s*\r?\n([\s\S]*?)\r?\n```/g,(_,template,html)=>{previews.push({template,html});return ''});return {markdown,previews}}
function renderHtmlPreviews(previews){return previews.map((preview,index)=>{const id=`inline-html-${index}-${Math.random().toString(36).slice(2)}`;setTimeout(async()=>{const frame=document.getElementById(id);if(!frame)return;try{const response=await fetch(`${base}/api/package-reference?path=${encodeURIComponent(preview.template)}`,{cache:'no-store'});if(!response.ok)throw new Error(`Template request failed: ${response.status}`);const shell=await response.text(),style=shell.match(/<style>[\s\S]*?<\/style>/i)?.[0]||'';frame.srcdoc=`<!doctype html><html><head><meta charset="utf-8">${style}</head><body><main class="page">${preview.html}</main></body></html>`}catch(error){frame.srcdoc=`<!doctype html><body><pre>${esc(error)}</pre></body>`}},0);return `<div class="inline-html-preview"><div><b>Rendered section HTML</b><span>${esc(preview.template)}</span></div><iframe id="${id}" title="Rendered section HTML" sandbox="allow-same-origin"></iframe><details><summary>Show section HTML</summary><pre><code>${esc(preview.html)}</code></pre></details></div>`}).join('')}
function attemptsFor(node,step){return run.stepAttempts?.[`${node.nodeKey}/${step.stepKey}`]||[]}
function stepCard(node,step){const r=resultFor(node,step),attempts=attemptsFor(node,step),correction=correctionFor(step.stepKey),isRunning=run.activeOperation?.nodeKey===node.nodeKey&&run.activeOperation?.stepKey===step.stepKey,state=isRunning?'running':r?.status||step.status||'pending',open=isRunning||!!correction||(!r&&['ready','blocked'].includes(node.status)),content=extractHtmlPreviews(stepBodyMarkdown(step.markdown));return `<details class="step-card ${esc(state)}" id="step-${slug(step.stepKey)}" ${open?'open':''}><summary>${isRunning?'<span class="spinner"></span>':''}<strong>${esc(step.stepTitle||`Step ${step.stepNumber}`)}</strong>${pill(state)}${attempts.length>1?`<span class="status-pill">${attempts.length} attempts</span>`:''}</summary><div class="step-body"><div class="step-copy markdown">${markdown(content.markdown)}${renderHtmlPreviews(content.previews)}</div>${correction?`<div class="error-banner"><b>Final validator correction</b><p>${esc(correction)}</p></div>`:''}${r?.status==='limited'?`<div class="error-banner"><b>Limited result—not complete</b><p>This attempt produced usable evidence but did not pass every acceptance criterion. It is retained for audit and retry guidance; downstream steps remain blocked.</p></div>`:''}${r?`<div class="result-summary"><b>${r.accepted&&r.status==='complete'?'Accepted current result':r.status==='limited'?'Current limited attempt':'Unaccepted result'}</b><div class="markdown">${markdown(r.finalMarkdown||r.summary||'No summary')}</div><small>Completed ${esc(r.completedAtUtc||'')} · Message ${esc(r.provenance?.messageKey||'')}</small>${attempts.at(-1)?.source==='session-correction'?'<p><b>Level 2 correction:</b> this attempt supersedes the earlier Step result.</p>':''}${r.provenance?.guidanceSnapshot?`<p><b>Guidance used:</b> ${esc(r.provenance.guidanceSnapshot)}</p>`:''}</div>${attempts.length>1?`<details><summary>Attempt history</summary>${attempts.map((a,i)=>`<div class="result-summary"><b>Attempt ${i+1}${a.accepted?' · current':''}</b><p>${esc(a.result?.summary||'')}</p><small>${esc(status(a.source))} · ${esc(a.sourceMessageKey||'')} ${a.supersedesAttemptId?'· supersedes prior attempt':''}</small></div>`).join('')}</details>`:''}${stepArtifacts(node,r)}`:'<div class="result-summary"><b>Not started</b><p>No accepted result is bound to this exact step.</p></div>'}<div class="guidance-panel"><label for="guide-${slug(step.stepKey)}">Guidance for this exact ${r?'rerun':'run'}</label><textarea id="guide-${slug(step.stepKey)}" placeholder="Describe what should be different. Leave blank for a normal run.">${esc(correction)}</textarea><div class="step-actions"><button class="button primary" data-run-step="${esc(step.stepKey)}" ${busy||run.activeOperation||node.status==='pending'?'disabled':''}>${r?'Rerun only this step':'Run only this step'}</button>${correction?'<span class="status-pill blocked">correction required</span>':r?.provenance?.guidanceSnapshot?'<span class="status-pill complete">guided result</span>':''}</div></div></div></details>`}
function promptSection(section){const id=`section-${slug(section.title)}`;return `<section class="section tracked prompt-section" id="${id}" data-label="${esc(section.title)}"><div class="head"><h2>${esc(section.title)}</h2><span>verbatim work prompt</span></div><div class="markdown">${markdown(section.markdown)}</div></section>`}
function workflowSection(node,section){const stepStart=section.markdown.search(/^###\s+Step\s+\d+:/m),preamble=stepStart>=0?section.markdown.slice(0,stepStart).trim():section.markdown;return `<section class="section tracked" id="section-workflow" data-label="Workflow"><div class="head"><h2>Workflow</h2><span>${node.stepDefinitions?.length||0} total · ${completedSteps(node)} done</span></div>${preamble?`<div class="workflow-definition"><div class="definition-label">WORKFLOW GUIDANCE · VERBATIM WORK PROMPT</div><div class="markdown">${markdown(preamble)}</div></div>`:''}<div class="children">${(node.stepDefinitions||[]).map(s=>stepCard(node,s)).join('')}</div></section>`}
function validatorSection(prompt){if(!prompt?.validationPrompt)return '';return `<section class="section tracked prompt-section" id="section-validator-contract" data-label="Validator Contract"><div class="head"><h2>Validator Contract</h2><span>verbatim validation prompt</span></div><div class="markdown">${markdown(prompt.validationPrompt)}</div></section>`}
function toc(node,parsed,prompt){const links=[];for(const section of parsed.sections){links.push(`<a class="navitem" href="#section-${slug(section.title)}">${esc(section.title)}</a>`);if(/^workflow$/i.test(section.title))for(const s of node.stepDefinitions||[]){const r=resultFor(node,s),running=run.activeOperation?.stepKey===s.stepKey;links.push(`<a class="navitem level3 ${r?.accepted&&r.status==='complete'?'done':''} ${running?'running':''}" href="#step-${slug(s.stepKey)}">${r?.accepted&&r.status==='complete'?'<span class="done-mark">✓</span>':''}${esc(s.stepNumber)}. ${esc(String(s.stepTitle||s.stepKey).replace(/^### Step \d+:?\s*/,''))}</a>`)}}if(prompt?.validationPrompt)links.push('<a class="navitem" href="#section-validator-contract">Validator Contract</a>');return `<aside class="toc"><div class="tochead"><b>Contents</b></div><div>${links.join('')}</div></aside>`}
function workflowView(){const node=activeNode();if(!node)return '<div class="empty-state">No graph node selected.</div>';const prompt=currentPrompts.get(node.nodeKey);if(!prompt)return `${overallOutput(node)}<div class="empty-state">Loading the complete bound prompt skill…</div>`;if(prompt.error)return `${overallOutput(node)}<div class="error-banner"><b>Bound prompt unavailable</b><p>${esc(prompt.error)}</p></div>`;const parsed=parsePrompt(prompt);const content=parsed.sections.map(section=>/^workflow$/i.test(section.title)?workflowSection(node,section):promptSection(section)).join('')+validatorSection(prompt);return `${overallOutput(node)}<section class="meta"><b>${esc(node.displayName)}</b><div>${esc(prompt.descriptor?.workPromptPath||node.workPromptPath)} · v${esc(node.skillVersion)} · work ${esc((prompt.descriptor?.workPromptHash||node.workPromptHash).slice(0,12))} · validation ${esc((prompt.descriptor?.validationPromptHash||node.validationPromptHash).slice(0,12))}</div><div class="node-summary"><div class="metric"><small>Status</small><b>${esc(status(node.status))}</b></div><div class="metric"><small>Dependency</small><b>${esc(status(node.dependencyStatus))}</b></div><div class="metric"><small>Accepted steps</small><b>${completedSteps(node)} / ${node.stepDefinitions?.length||0}</b></div><div class="metric"><small>Adapter</small><b>${esc(node.executionAdapter)}</b></div></div></section><div class="structured-shell">${toc(node,parsed,prompt)}<div class="promptbody">${content}</div></div>`}
function allArtifacts(){const cards=[];for(const n of nodes()){for(const a of n.overallResult?.artifacts||[])cards.push({n,a,overall:true});for(const r of Object.values(n.stepResults||{}))for(const a of r.artifacts||[])cards.push({n,a,overall:false})}return `<section class="section"><div class="head"><h2>Bound artifacts</h2><span>${cards.length} files</span></div><div class="children artifact-grid">${cards.length?cards.map(({n,a,overall})=>`<div class="artifact-card"><h3>${esc(a.fileName||a.artifactKey)}</h3><p>${esc(n.displayName)} · ${overall?'skill output':'step artifact'} · ${esc(a.mediaType)}</p><a class="button ${overall?'primary':''}" href="${esc(artifactUrl(n.nodeKey,a))}" target="_blank">Open artifact</a></div>`).join(''):'<div class="empty-state">No artifacts are bound yet.</div>'}</div></section>`}
function graphView(){const ns=nodes();return `<section class="section"><div class="head"><h2>Package-owned skill graph</h2><span>${esc(run.graphFingerprint)}</span></div><div class="children"><div class="graph-flow">${ns.map((n,i)=>`${i?'<div class="graph-arrow">→</div>':''}<div class="graph-node ${n.nodeKey===run.rootSkill?'root':''}"><h3>${esc(n.displayName)}</h3><p>${esc(n.actionPrototype)}</p>${pill(n.status)} ${pill(n.dependencyStatus)}<p>${completedSteps(n)}/${n.stepDefinitions?.length||0} steps</p></div>`).join('')}</div><h3>Resolved edges</h3><pre class="raw-state">${esc(JSON.stringify(run.edges||[],null,2))}</pre></div></section>`}
function rawPromptsView(){const node=activeNode(),prompt=node&&currentPrompts.get(node.nodeKey);if(!node)return '<div class="empty-state">No graph node selected.</div>';if(!prompt)return '<div class="loading">Loading the exact bound prompt skill source…</div>';if(prompt.error)return `<div class="error-banner"><b>Bound prompt unavailable</b><p>${esc(prompt.error)}</p></div>`;const d=prompt.descriptor||{};return `<section class="raw-prompts"><div class="raw-prompts-intro"><div><small>BOUND PROMPT SKILL SOURCE</small><h2>${esc(node.displayName)}</h2><p>Verbatim package-owned prompt text, loaded only when its current hashes match this run.</p></div><span>${esc(node.actionPrototype)}</span></div><section class="raw-prompt-panel"><div class="raw-prompt-head"><div><h3>Work prompt</h3><code>${esc(d.workPromptPath||node.workPromptPath)}</code></div><span>SHA-256 ${esc(d.workPromptHash||node.workPromptHash)}</span></div><pre>${esc(prompt.workPrompt)}</pre></section><section class="raw-prompt-panel"><div class="raw-prompt-head"><div><h3>Validation prompt</h3><code>${esc(d.validationPromptPath||node.validationPromptPath)}</code></div><span>SHA-256 ${esc(d.validationPromptHash||node.validationPromptHash)}</span></div><pre>${esc(prompt.validationPrompt||'No separate validation prompt is bound.')}</pre></section></section>`}
function render(){if(view==='settings'){renderSettings();return}if(!run){setup();return}document.querySelector('header p').textContent=`${run.runKey} · ${status(run.initializationStatus)} · revision ${run.revision}`;app.className='';app.innerHTML=`${runBar()}${view==='workflow'?workflowView():view==='prompts'?rawPromptsView():view==='artifacts'?allArtifacts():view==='graph'?graphView():`<pre class="raw-state">${esc(JSON.stringify(run,null,2))}</pre>`}`;bind()}
function bind(){document.querySelector('[data-batch-start]')?.addEventListener('click',()=>batch('start'));document.querySelector('[data-final-validate]')?.addEventListener('click',validateFinal);document.querySelector('[data-batch-pause]')?.addEventListener('click',()=>batch('pause'));document.querySelector('[data-batch-resume]')?.addEventListener('click',()=>batch('resume'));document.querySelector('[data-prime]')?.addEventListener('click',prime);document.querySelector('[data-reload-workflow]')?.addEventListener('click',reloadSkillWorkflow);document.querySelector('[data-add-skill]')?.addEventListener('click',openAddSkill);document.querySelector('[data-add-skill-search]')?.addEventListener('input',event=>searchAddSkills(event.target.value));document.querySelector('[data-add-skill-cancel]')?.addEventListener('click',()=>{addSkillOpen=false;render()});document.querySelectorAll('[data-add-skill-pick]').forEach(button=>button.onclick=()=>addSkill(button.dataset.addSkillPick));document.querySelectorAll('[data-run-step]').forEach(b=>b.onclick=()=>runStep(activeNodeKey,b.dataset.runStep));document.querySelectorAll('[data-light-preview]').forEach(frame=>{const enforceLight=()=>{try{const doc=frame.contentDocument;if(!doc)return;doc.documentElement.style.colorScheme='light';doc.documentElement.style.background='#fff';if(doc.body){doc.body.style.colorScheme='light';doc.body.style.background='#fff'}}catch{}};frame.addEventListener('load',enforceLight);enforceLight()})}
async function searchAddSkills(query=''){try{const response=await promptSkills.SearchPromptSkills(query,30,false);addSkillOptions=response.items||[];addSkillOpen=true;busy='';notice='Select any installed skill to load into this run session.';noticeError=false;render();const input=document.querySelector('[data-add-skill-search]');if(input){input.value=query;input.focus()}}catch(e){busy='';notice=e.message;noticeError=true;render()}}
async function openAddSkill(){busy='add-skill-search';notice='Loading the full Buffaly skill catalog...';noticeError=false;render();await searchAddSkills('')}
async function addSkill(prototype){try{busy='add-skill';notice=`Loading ${prototype} into ${run.sessionKey} and adding it to this run...`;noticeError=false;render();run=await runsApi.AddSkill(run.runKey,run.revision,prototype);activeNodeKey=run.rootSkill;currentPrompts.delete(activeNodeKey);addSkillOpen=false;busy='';notice='Skill added. Prime the same session before running its steps.';renderTabs();await loadPrompt(activeNodeKey);render()}catch(e){busy='';notice=e.message;noticeError=true;render()}}
async function reloadSkillWorkflow(){const node=run.nodes?.[activeNodeKey];if(!node)return;if(!confirm(`Reload ${node.displayName} from its latest package workflow? Existing accepted results and overall output for this skill will be cleared. Other skills and their artifacts remain unchanged.`))return;try{busy='reload-workflow';notice=`Reloading ${node.displayName} from the latest package workflow...`;noticeError=false;render();run=await runsApi.ReloadSkillWorkflow(run.runKey,activeNodeKey,run.revision);currentPrompts.delete(activeNodeKey);busy='';notice='Skill workflow reloaded. Prime the run before executing its latest steps.';renderTabs();await loadPrompt(activeNodeKey);render()}catch(e){busy='';notice=e.message;noticeError=true;render()}}
async function prime(){try{busy='prime';notice=run.activeOperation?'Superseding the active step and starting a fresh Prime...':'Priming run contract...';noticeError=false;render();await runsApi.Prime(run.runKey, run.revision, `ui-prime-${Date.now()}`);notice='Prime acknowledged.';await load()}catch(e){const staleSuperseded=e.message.includes('superseded')||e.message.includes('revision');busy='';await load(true);if(staleSuperseded&&run.initializationStatus==='primed'){notice='Prime acknowledged.';noticeError=false;render();return}notice=e.message;noticeError=true;render()}}
async function stopBatch(){const op=run.activeOperation;if(!op||op.health!=='stale')return;try{busy='batch-stop';notice='Stopping the stale batch operation...';noticeError=false;render();run=await runsApi.StopBatch(run.runKey,run.revision,op.operationId,`User stopped stale batch operation ${op.operationId}/${op.stepKey}: ${op.healthReason||'worker recovery failed'}`);busy='';notice='Stale batch stopped. Use Run remaining steps to retry the blocked step.';renderTabs();render()}catch(e){busy='';notice=e.message;noticeError=true;render()}}
async function batch(command){try{busy=`batch-${command}`;notice=`Sending batch ${command} command...`;noticeError=false;render();const result=command==='start'?await runsApi.StartBatch(run.runKey, run.revision):command==='pause'?await runsApi.PauseBatch(run.runKey, run.revision):await runsApi.ResumeBatch(run.runKey, run.revision);notice=command==='start'?`Batch ${status(result.status)}${result.currentNodeKey?` at ${result.currentNodeKey}`:''}.`: `Batch ${status(result.status)}.`;noticeError=false;await load()}catch(e){notice=e.message;noticeError=true;busy='';render()}}
async function validateFinal(){try{busy='final-validation';notice='Running the independent final validator against the candidate deliverables...';noticeError=false;render();await runsApi.ValidateFinal(run.runKey, run.revision, `ui-final-validation-${Date.now()}`);await load(true);notice=run.finalValidation?.status==='passed'?'Final validation passed; the run is complete.':'Final validation failed. The correction plan is mapped to the affected steps below.';noticeError=run.finalValidation?.status!=='passed';render()}catch(e){notice=e.message;noticeError=true;busy='';await load(true)}}
async function runStep(nodeKey,stepKey){try{const guide=document.querySelector(`#guide-${CSS.escape(slug(stepKey))}`)?.value||'';busy=stepKey;notice=guide?'Running selected step with your guidance...':'Running selected step...';noticeError=false;render();await runsApi.RunStep(run.runKey, nodeKey, stepKey, run.revision, `ui-${Date.now()}`, guide, true);notice='Step result accepted.';await load(true)}catch(e){notice=e.message;noticeError=true;busy='';await load(true)}}
async function loadPrompt(nodeKey){if(currentPrompts.has(nodeKey))return;currentPrompts.set(nodeKey,null);try{currentPrompts.set(nodeKey,await runsApi.GetNodePrompt(run.runKey, nodeKey))}catch(e){currentPrompts.set(nodeKey,{error:e.message})}}
async function load(silent=false){if(!runKey){app.innerHTML='<div class="notfound">Open this page with a bound run link: <code>?run=&lt;run-key&gt;</code>.</div>';return}try{await loadConfiguredPublicUiOrigin();const latest=await runsApi.GetRun(runKey),changed=!run||latest.revision!==run.revision;run=latest;if(!activeNodeKey||!run.nodes?.[activeNodeKey])activeNodeKey=run.rootSkill||nodes()[0]?.nodeKey;await loadPrompt(activeNodeKey);busy='';if(changed||!silent){renderTabs();render()}}catch(e){app.innerHTML=`<div class="error-banner"><b>Unable to load run</b><p>${esc(e.message)}</p></div>`}}
const hiddenSetupInputs=new Set(['sessionKey','sourceEvidencePaths','websiteAudit','websiteAuditArtifacts']);
function toInputKey(name){const n=String(name||'');return n?n[0].toLowerCase()+n.slice(1):''}
function prettyInput(name){return String(name||'').replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()).trim()}
function schemaInputNames(schema){return Object.keys(schema?.properties||{}).filter(k=>!hiddenSetupInputs.has(k))}
function visibleInputNames(descriptor){const declared=(descriptor.inputs||[]).map(toInputKey).filter(Boolean);return declared.length?declared:schemaInputNames(descriptor.inputSchema||descriptor.InputSchema)}
function requiredInputGroups(schema){const groups=[];for(const clause of schema?.anyOf||[]){const req=(clause.required||[]).map(toInputKey).filter(k=>k&&!hiddenSetupInputs.has(k));if(req.length)groups.push(req)}const top=(schema?.required||[]).map(toInputKey).filter(k=>k&&!hiddenSetupInputs.has(k));if(top.length)groups.push(top);return groups}
function inputChoiceNote(descriptor){const names=visibleInputNames(descriptor),schema=descriptor.inputSchema||descriptor.InputSchema||{};if(names.includes('leadId')&&names.includes('companyName')&&names.includes('websiteUrl'))return `<div class="input-choice-note"><strong>Identity required</strong><span>Enter a Lead ID, Company Name, or Website URL.</span></div>`;if(names.includes('leadId')&&names.includes('companyName'))return `<div class="input-choice-note"><strong>Lead required</strong><span>Enter a Lead ID, or use Company Name when a CRM lead is not available.</span></div>`;const groups=requiredInputGroups(schema);if(!groups.length)return '';return `<div class="input-choice-note"><strong>Required</strong><span>Provide ${esc(groups.map(g=>g.map(prettyInput).join(' + ')).join(', or '))}.</span></div>`}
function requireCollectedInputs(inputs,descriptor){const schema=descriptor.inputSchema||descriptor.InputSchema||{},groups=requiredInputGroups(schema),names=visibleInputNames(descriptor);if(groups.length){if(!groups.some(g=>g.every(k=>inputs[k])))throw new Error(`Enter ${groups.map(g=>g.map(prettyInput).join(' + ')).join(', or ')}.`);return}if((names.includes('leadId')||names.includes('companyName'))&&!inputs.leadId&&!inputs.companyName)throw new Error('Enter a Lead ID or Company Name.')}
function summarizeInputs(inputs){if(inputs.leadId)return `Lead ${inputs.leadId}`;if(inputs.companyName)return inputs.companyName;if(inputs.websiteUrl)return inputs.websiteUrl;const entries=Object.entries(inputs);return entries.length?entries.map(([k,v])=>`${prettyInput(k)} ${v}`).join(', '):'none'}
function setupField(name){const key=toInputKey(name),id=`setup-${slug(key)}`,label=prettyInput(name),placeholder=key==='leadId'?'e.g. 67230':key==='companyName'?'Use when no lead ID is available':key==='websiteUrl'?'https://example.com':key==='location'?'City, state, or market':'';if(key==='presenterMode')return `<label class="setup-field" for="${id}"><span>${esc(label)}</span><select id="${id}" data-input-name="${esc(key)}"><option value="IntelligenceFactoryDirect">Intelligence Factory Direct</option><option value="ClearSpanPartner">ClearSpan Partner</option></select></label>`;return `<label class="setup-field" for="${id}"><span>${esc(label)}</span><input id="${id}" type="${key==='websiteUrl'?'url':'text'}" data-input-name="${esc(key)}" placeholder="${esc(placeholder)}"></label>`}
function suggestedRunKey(skill){const base=skill.replace(/^To/,'').replace(/Skill$/,'').replace(/([a-z])([A-Z])/g,'$1-$2').toLowerCase();return `${base}-${new Date().toISOString().slice(0,10).replaceAll('-','')}`}
async function setup(){
 let selected=skillKey,descriptor=null,resolution=null,setupSessionKey='',sessionConnected=false;let connectionNote='';
 try{const conn=await connections.GetConnection();currentPublicUiOrigin=normalizeOrigin(conn.connection?.publicUiOrigin);if(!conn.isPersisted)connectionNote='<div class="notfound">Using unsaved process defaults. Open Settings to test and persist a Buffaly connection.</div>'}catch(e){connectionNote=`<div class="error-banner"><b>Connection check failed</b><p>${esc(e.message)}</p></div>`}
 app.innerHTML=`<div class="setup-shell"><section class="setup-hero"><div><span class="setup-eyebrow">General Skill Workbench</span><h1>Create a new skill run</h1><p>Connect a Buffaly session first, then load a prompt skill into that session before creating its run.</p></div><ol class="setup-steps"><li class="active">Connect session</li><li>Choose skill</li><li>Provide inputs</li><li>Review and create</li></ol></section>${connectionNote}<section class="setup-card" data-session-card><div class="setup-card-head"><div><span class="setup-number">1</span><h2>Connect a Buffaly session</h2></div><p>The selected prompt action will be loaded into this session.</p></div><div class="setup-run-fields"><label class="setup-field"><span>Buffaly session name</span><input data-setup-session value="gsw-${Date.now()}"><small>Create and bind the session before choosing a skill.</small></label><button class="button primary setup-primary" data-connect-session>Connect session <span>→</span></button><div data-session-status></div></div></section><section class="setup-card muted" data-skill-card><div class="setup-card-head"><div><span class="setup-number">2</span><h2>Choose a prompt skill</h2></div><p>After selection, Workbench loads the action and verifies both prompt files in the connected session.</p></div><div class="setup-search-row"><label class="setup-search"><span>Search skills</span><input data-skill-search value="${esc(skillKey)}" placeholder="Connect a session first" disabled></label><button class="button" data-reload-skills disabled>Reload skills</button></div><div data-reload-status></div><div class="skill-results" data-skill-results><div class="setup-placeholder">Connect a session to browse skills.</div></div><div data-selected-skill></div></section><section class="setup-card muted" data-input-card><div class="setup-card-head"><div><span class="setup-number">3</span><h2>Provide skill inputs</h2></div><p>Choose a skill to load its required fields.</p></div><div class="setup-placeholder">No skill selected yet.</div></section><section class="setup-card muted" data-create-card><div class="setup-card-head"><div><span class="setup-number">4</span><h2>Review and create run</h2></div><p>The run will use the already connected session.</p></div><div class="setup-placeholder">Complete the skill inputs first.</div></section></div>`;
 const skillTitle=s=>s.title||s.displayName||readablePrototype(s.prototypeName);
 const readablePrototype=name=>(name||'').replace(/^To/,'').replace(/Skill$/,'').replace(/([a-z])([A-Z])/g,'$1 $2');
  let refreshCatalog=true;
  const showSkills=async()=>{if(!sessionConnected)return;const q=document.querySelector('[data-skill-search]').value;const refresh=refreshCatalog;refreshCatalog=false;const response=await promptSkills.SearchPromptSkills(q,30,refresh);const skills=response.items||[];document.querySelector('[data-skill-results]').innerHTML=skills.length?skills.map(s=>`<button type="button" class="skill-option ${selected===s.prototypeName?'selected':''}" data-pick="${esc(s.prototypeName)}"><span class="skill-icon">${s.isRunnable?'+':'-'}</span><span><strong>${esc(skillTitle(s))}</strong><small>${esc(s.prototypeName)}</small>${!s.isRunnable?`<em class="disabled-note">Runtime verification required</em>`:''}</span><span class="skill-arrow">&gt;</span></button>`).join(''):'<div class="setup-placeholder">No matching skills found.</div>';document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>pickSkill(b.dataset.pick))};
  const reloadSkills=async()=>{if(!sessionConnected)return;const button=document.querySelector('[data-reload-skills]'),status=document.querySelector('[data-reload-status]');button.disabled=true;status.innerHTML='<div class="setup-inline-status">Reloading package and runtime skill catalogs…</div>';try{refreshCatalog=true;descriptor=null;resolution=null;selected='';document.querySelector('[data-selected-skill]').innerHTML='';resetCreateCard();await showSkills();status.innerHTML='<div class="setup-inline-status success">Skills reloaded. Select the skill again to use its latest workflow.</div>'}catch(e){status.innerHTML=`<div class="error-banner"><b>Skill reload failed</b><p>${esc(e.message)}</p></div>`}finally{button.disabled=false}};
 const resetCreateCard=()=>{const card=document.querySelector('[data-create-card]');card.classList.add('muted');card.innerHTML=`<div class="setup-card-head"><div><span class="setup-number">4</span><h2>Review and create run</h2></div><p>The run will use the already connected session.</p></div><div class="setup-placeholder">Complete the skill inputs first.</div>`};
  const pickSkill=async prototype=>{if(!sessionConnected)return;selected=prototype;const selectedPanel=document.querySelector('[data-selected-skill]');try{const detail=await promptSkills.GetPromptSkill(selected,false);const item=detail.item||detail.Item||{};const execution=detail.executionDescriptor||detail.ExecutionDescriptor||null;resolution=null;const title=execution?.displayName||item.title||readablePrototype(item.prototypeName||item.PrototypeName||prototype);document.querySelector('[data-skill-search]').value=title;selectedPanel.innerHTML=`<div class="selected-skill"><span>Loading into ${esc(setupSessionKey)}…</span><strong>${esc(title)}</strong><code>${esc(execution?.actionPrototype||item.prototypeName||item.PrototypeName||prototype)}</code></div>`;const loaded=await promptSkills.PreparePromptSkill(setupSessionKey,execution?.actionPrototype||prototype);descriptor=execution||{actionPrototype:item.prototypeName||item.PrototypeName||prototype,displayName:title,executionAdapter:'protoscript-action/v1',inputs:[],inputSchema:{}};selectedPanel.innerHTML=`<div class="selected-skill"><span>Loaded in ${esc(setupSessionKey)}</span><strong>${esc(title)}</strong><code>${esc(loaded.prototypeName||prototype)} · ${execution?'Workbench overlay':'session-native execution'}</code></div>`;await showSkills();renderInputs()}catch(e){descriptor=null;selectedPanel.innerHTML=`<div class="error-banner"><b>Could not load skill into this session</b><p>${esc(e.message)}</p></div>`;resetCreateCard()}};
  const renderInputs=()=>{const names=visibleInputNames(descriptor),fields=names.map(setupField).join(''),generic=!names.length&&descriptor.executionAdapter==='protoscript-action/v1';const card=document.querySelector('[data-input-card]');card.classList.remove('muted');card.innerHTML=`<div class="setup-card-head"><div><span class="setup-number">3</span><h2>Provide skill inputs</h2></div><p>${esc(descriptor.displayName)}</p></div>${inputChoiceNote(descriptor)}<div class="setup-form-grid">${generic?'<label class="setup-field setup-field-wide"><span>Instructions and inputs</span><textarea data-input-name="instructions" rows="8" placeholder="Describe what this prompt skill should do, including all names, URLs, constraints, and desired deliverables."></textarea><small>The bound Buffaly session receives this text when it executes the loaded action.</small></label>':fields||'<div class="setup-placeholder">This overlay defines no user-facing inputs.</div>'}</div><div class="setup-actions"><button class="button primary setup-primary" data-resolve>Review skill graph <span>→</span></button></div>`;card.querySelector('[data-resolve]').onclick=resolveGraph};
 const collectInputs=()=>{const inputs={};document.querySelectorAll('[data-input-name]').forEach(el=>{if(el.value!=='')inputs[el.dataset.inputName]=el.value});return inputs};
  const resolveGraph=async()=>{const target=document.querySelector('[data-create-card]');try{const inputs=collectInputs();requireCollectedInputs(inputs,descriptor);resolution=await skillGraphs.Resolve(selected,inputs,[]);target.classList.remove('muted');const graphNodes=(resolution.nodes||[]).map((n,i)=>`<div class="setup-graph-node"><span>${i+1}</span><div><strong>${esc(n.displayName)}</strong><small>${esc(n.stepDefinitions?.length||0)} workflow steps</small></div></div>`).join('<div class="setup-graph-arrow">↓</div>');target.innerHTML=`<div class="setup-card-head"><div><span class="setup-number">4</span><h2>Review and create run</h2></div><p>Resolved from the loaded ProtoScript action${descriptor.executionAdapter==='protoscript-action/v1'?'':' and its Workbench overlay'} and bound to ${esc(setupSessionKey)}.</p></div><div class="setup-review"><div><h3>Resolved skill graph</h3><div class="setup-graph">${graphNodes}</div></div><div class="setup-run-fields"><label class="setup-field"><span>Run key</span><input data-new-run value="${esc(suggestedRunKey(selected))}"><small>A unique, URL-safe name for this run.</small></label><div class="setup-summary"><span>Buffaly session</span><strong>${esc(setupSessionKey)}</strong><span>Prompt skill</span><strong>${esc(descriptor.displayName)}</strong><span>Input</span><strong>${esc(summarizeInputs(inputs))}</strong><span>Steps</span><strong>${resolution.nodes.reduce((sum,n)=>sum+(n.stepDefinitions?.length||0),0)}</strong></div><button class="button primary setup-primary" data-materialize>Create run <span>→</span></button></div></div>`;target.querySelector('[data-materialize]').onclick=materialize;target.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){target.classList.remove('muted');target.innerHTML=`<div class="error-banner"><b>Unable to resolve this skill</b><p>${esc(e.message)}</p></div>`}};
 const materialize=async()=>{try{const newRunKey=document.querySelector('[data-new-run]').value.trim();if(!newRunKey)throw new Error('Enter a run key.');const button=document.querySelector('[data-materialize]');button.disabled=true;button.textContent='Creating run…';const created=await runsApi.MaterializeFromGraph(resolution.resolutionId,resolution.fingerprint,newRunKey,null,setupSessionKey,{});location.href=`/?run=${encodeURIComponent(created.runKey)}`}catch(e){const target=document.querySelector('[data-create-card]');target.insertAdjacentHTML('beforeend',`<div class="error-banner"><b>Unable to create run</b><p>${esc(e.message)}</p></div>`);document.querySelector('[data-materialize]')?.removeAttribute('disabled')}};
  const connectSession=async()=>{const button=document.querySelector('[data-connect-session]'),status=document.querySelector('[data-session-status]');try{setupSessionKey=document.querySelector('[data-setup-session]').value.trim();if(!setupSessionKey)throw new Error('Enter a Buffaly session name.');button.disabled=true;button.textContent='Connecting…';await promptSkills.ConnectSession(setupSessionKey);sessionConnected=true;document.querySelector('[data-setup-session]').readOnly=true;document.querySelector('[data-skill-card]').classList.remove('muted');const search=document.querySelector('[data-skill-search]'),reload=document.querySelector('[data-reload-skills]');search.disabled=false;search.placeholder='Search by skill name or action prototype';search.oninput=showSkills;reload.disabled=false;reload.onclick=reloadSkills;status.innerHTML=`<div class="operation-banner"><b>Session connected</b><p>${esc(setupSessionKey)} is ready for prompt skill loading.</p></div>`;button.textContent='Connected';await showSkills();if(selected)await pickSkill(selected)}catch(e){sessionConnected=false;button.disabled=false;button.textContent='Connect session →';status.innerHTML=`<div class="error-banner"><b>Unable to connect session</b><p>${esc(e.message)}</p></div>`}};
 document.querySelector('[data-connect-session]').onclick=connectSession
}viewButtons.forEach(b=>b.onclick=()=>{view=b.dataset.view;viewButtons.forEach(x=>x.classList.toggle('active',x===b));if(view==='settings')renderSettings();else if(run)render();else setup()});
async function renderSettings(){
const app=document.querySelector('#app');
app.innerHTML=`<section class="setup-shell"><section class="setup-hero"><div><span class="setup-eyebrow">Settings</span><h1>Buffaly Connection</h1><p>Configure the Buffaly instance used for catalog discovery and workflow execution.</p></div></section><section class="setup-card"><div class="setup-card-head"><div><h2>Connection settings</h2></div><p>Test before saving. Saving invalidates the catalog cache.</p></div><div id="settings-form" class="setup-form-grid"><label class="setup-field"><span>Display name</span><input data-cfg-displayname placeholder="Marketing Buffaly"></label><label class="setup-field"><span>Buffaly URL</span><input data-cfg-baseurl placeholder="http://127.0.0.1:58177"></label><label class="setup-field"><span>Public UI origin</span><input data-cfg-publicui placeholder="https://buffaly.example:10584"><small>Browser session links use this when the API URL is loopback-only.</small></label><label class="setup-field"><span>Project</span><input data-cfg-projectname placeholder="OpsAgent"></label><label class="setup-field"><span>Agent</span><input data-cfg-agentname placeholder="workbench-agent"></label><label class="setup-field"><span>Request timeout (seconds)</span><input type="number" data-cfg-requesttimeout value="30"></label><label class="setup-field"><span>Operation timeout (minutes)</span><input type="number" data-cfg-operationtimeout value="20"></label><label class="setup-field"><span>Poll interval (ms)</span><input type="number" data-cfg-pollinterval value="2000"></label></div><div class="setup-actions"><button class="button" data-test-connection>Test connection</button><button class="button primary" data-save-connection disabled>Save connection</button></div><div id="settings-test-result"></div><div id="settings-error"></div></section></section>`;
try{const resp=await connections.GetConnection();connectionState=resp.connection;currentPublicUiOrigin=normalizeOrigin(connectionState?.publicUiOrigin);settingsDirty=false,addSkillOpen=false,addSkillOptions=[];testResult=null;if(connectionState){document.querySelector('[data-cfg-displayname]').value=connectionState.displayName||'';document.querySelector('[data-cfg-baseurl]').value=connectionState.baseUrl||'';document.querySelector('[data-cfg-publicui]').value=connectionState.publicUiOrigin||'';document.querySelector('[data-cfg-projectname]').value=connectionState.projectName||'';document.querySelector('[data-cfg-agentname]').value=connectionState.agentName||'';document.querySelector('[data-cfg-requesttimeout]').value=connectionState.requestTimeoutSeconds||30;document.querySelector('[data-cfg-operationtimeout]').value=connectionState.operationTimeoutMinutes||20;document.querySelector('[data-cfg-pollinterval]').value=connectionState.pollIntervalMilliseconds||2000;}if(!resp.isPersisted){document.querySelector('#settings-test-result').innerHTML='<div class="notfound">Not yet configured. These values come from process configuration and are not saved. Test and save to persist.</div>';}}catch(e){document.querySelector('#settings-error').innerHTML=`<div class="error-banner"><b>Failed to load settings</b><p>${esc(e.message)}</p></div>`;}
document.querySelectorAll('[data-cfg-displayname],[data-cfg-baseurl],[data-cfg-publicui],[data-cfg-projectname],[data-cfg-agentname],[data-cfg-requesttimeout],[data-cfg-operationtimeout],[data-cfg-pollinterval]').forEach(el=>el.oninput=()=>{settingsDirty=true;testResult=null;document.querySelector('[data-save-connection]').disabled=true;document.querySelector('#settings-test-result').innerHTML='';});
document.querySelector('[data-test-connection]').onclick=async()=>{const candidate={DisplayName:document.querySelector('[data-cfg-displayname]').value,BaseUrl:document.querySelector('[data-cfg-baseurl]').value,PublicUiOrigin:document.querySelector('[data-cfg-publicui]').value,ProjectName:document.querySelector('[data-cfg-projectname]').value,AgentName:document.querySelector('[data-cfg-agentname]').value,RequestTimeoutSeconds:parseInt(document.querySelector('[data-cfg-requesttimeout]').value)||30,OperationTimeoutMinutes:parseInt(document.querySelector('[data-cfg-operationtimeout]').value)||20,PollIntervalMilliseconds:parseInt(document.querySelector('[data-cfg-pollinterval]').value)||2000};const btn=document.querySelector('[data-test-connection]');btn.disabled=true;btn.textContent='Testing...';try{const result=await connections.TestConnection(candidate);testResult=result;if(result.success){document.querySelector('#settings-test-result').innerHTML=`<div class="found"><b>Connection successful</b><p>Project: ${esc(result.projectName)} | Prompt actions: ${result.promptActionCount} | Generated: ${esc(result.catalogGeneratedAt||'unknown')} | Diagnostics: ${result.diagnosticsCount||0} | Elapsed: ${result.elapsedMilliseconds}ms</p></div>`;document.querySelector('[data-save-connection]').disabled=false;}else{document.querySelector('#settings-test-result').innerHTML=`<div class="error-banner"><b>Connection failed</b><p>${esc(result.errorCode||'unknown')}: ${esc(result.errorMessage||'No details')}</p></div>`;document.querySelector('[data-save-connection]').disabled=true;}}catch(e){document.querySelector('#settings-test-result').innerHTML=`<div class="error-banner"><b>Connection failed</b><p>${esc(e.message)}</p></div>`;}finally{btn.disabled=false;btn.textContent='Test connection';}};
document.querySelector('[data-save-connection]').onclick=async()=>{const candidate={DisplayName:document.querySelector('[data-cfg-displayname]').value,BaseUrl:document.querySelector('[data-cfg-baseurl]').value,PublicUiOrigin:document.querySelector('[data-cfg-publicui]').value,ProjectName:document.querySelector('[data-cfg-projectname]').value,AgentName:document.querySelector('[data-cfg-agentname]').value,RequestTimeoutSeconds:parseInt(document.querySelector('[data-cfg-requesttimeout]').value)||30,OperationTimeoutMinutes:parseInt(document.querySelector('[data-cfg-operationtimeout]').value)||20,PollIntervalMilliseconds:parseInt(document.querySelector('[data-cfg-pollinterval]').value)||2000};const expectedRev=connectionState?.revision||0;const btn=document.querySelector('[data-save-connection]');btn.disabled=true;btn.textContent='Saving...';try{const result=await connections.SaveConnection(candidate,expectedRev);connectionState=result.settings;testResult=result.testResult;settingsDirty=false,addSkillOpen=false,addSkillOptions=[];document.querySelector('#settings-test-result').innerHTML=`<div class="found"><b>Saved successfully</b><p>Revision ${result.settings.revision} | Project: ${esc(result.testResult.projectName)} | Prompt actions: ${result.testResult.promptActionCount}</p></div>`;}catch(e){document.querySelector('#settings-error').innerHTML=`<div class="error-banner"><b>Save failed</b><p>${esc(e.message)}</p></div>`;}finally{btn.disabled=false;btn.textContent='Save connection';}};
}
if(params.get('view')==='settings'){view='settings';viewButtons.forEach(b=>b.classList.toggle('active',b.dataset.view==='settings'));renderSettings()}else if(runKey){load();setInterval(()=>load(true),5000)}else setup();

